-- Generated from the creator-approved 67-card edition and 105 uniformized public artwork references.
-- APPLY ONLY AFTER VALIDATING ALL 105 PUBLIC HTTP URLs; run this on the EXISTING Floot database.
-- Does NOT delete, update or otherwise expose the private mystery card.
-- Does NOT change inventories, histories, rarities, cooldowns or authentication.
-- Idempotent: rerunning the same migration leaves already normalized assets unchanged.
BEGIN;
CREATE TEMP TABLE _tcg_uniform_artwork_map (
  card_id text PRIMARY KEY,
  card_name text NOT NULL,
  previous_main_url text NOT NULL,
  new_main_url text NOT NULL,
  previous_variants jsonb NOT NULL,
  new_variants jsonb NOT NULL
) ON COMMIT DROP;
DO $tcg_preflight$
BEGIN
  IF (SELECT COUNT(*) FROM _tcg_uniform_artwork_map) <> 67
    OR (SELECT COUNT(*) FROM tcg_cards_origin WHERE normal_booster = TRUE) <> 67
    OR (SELECT COUNT(*) FROM tcg_cards_origin live JOIN _tcg_uniform_artwork_map stage
           ON live.id = stage.card_id WHERE live.normal_booster = TRUE) <> 67
  THEN RAISE EXCEPTION 'Approved 67-card staging does not match current Floot edition'; END IF;
  IF EXISTS (
    SELECT 1 FROM tcg_cards_origin live
      JOIN _tcg_uniform_artwork_map stage ON live.id = stage.card_id
    WHERE NOT live.normal_booster
       OR live.name IS DISTINCT FROM stage.card_name
       OR (live.image_path IS DISTINCT FROM stage.previous_main_url
          AND live.image_path IS DISTINCT FROM stage.new_main_url)
       OR (live.variants IS DISTINCT FROM stage.previous_variants
          AND live.variants IS DISTINCT FROM stage.new_variants)
  ) THEN RAISE EXCEPTION 'Live Floot artwork changes since preparation: stop migration and investigate'; END IF;
END $tcg_preflight$;
UPDATE tcg_cards_origin live SET
  image_path = stage.new_main_url,
  variants = stage.new_variants
FROM _tcg_uniform_artwork_map stage
WHERE live.id = stage.card_id AND live.normal_booster = TRUE
  AND (live.image_path IS DISTINCT FROM stage.new_main_url
    OR live.variants IS DISTINCT FROM stage.new_variants);
DO $tcg_postflight$
BEGIN
  IF (SELECT COUNT(*) FROM tcg_cards_origin live
    JOIN _tcg_uniform_artwork_map stage ON stage.card_id = live.id
    WHERE live.normal_booster = TRUE
      AND live.image_path = stage.new_main_url
      AND live.variants = stage.new_variants) <> 67
  THEN RAISE EXCEPTION 'Post-migration artwork verification failed'; END IF;
END $tcg_postflight$;
COMMIT;
